import {
  CharacterRig,
  type CharacterAssetUrls,
  type CharacterLoadResult,
} from "../../../render/objects/CharacterRig";

export interface PreparedLearningPathCharacter {
  readonly character: CharacterRig;
  readonly ready: Promise<CharacterLoadResult>;
}

const getCharacterAssetUrl = (fileName: string): string => (
  `${import.meta.env.BASE_URL}assets/${fileName}`
);

export const getDefaultCharacterAssetUrls = (): CharacterAssetUrls => ({
  run: getCharacterAssetUrl("liu-kanshan-run.glb"),
  runStop: getCharacterAssetUrl("liu-kanshan-run-stop.glb"),
  idle: getCharacterAssetUrl("liu-kanshan-idle.glb"),
  turn: getCharacterAssetUrl("liu-kanshan-turn.glb"),
});

/**
 * Starts GLB fetch, parse and animation normalization without constructing the
 * scene session. Importing this module at the generation gate intentionally
 * warms only Three core, GLTFLoader, CharacterRig and the four character GLBs.
 */
export function prepareLearningPathCharacter(
  assetUrls: CharacterAssetUrls = getDefaultCharacterAssetUrls(),
): PreparedLearningPathCharacter {
  const character = new CharacterRig();
  const ready = character.load(assetUrls);
  // The owning bootstrap/session still awaits and reports the original promise;
  // this observer only prevents an early gate-time preload from being unhandled.
  void ready.catch(() => {});
  return Object.freeze({ character, ready });
}
